unsigned int EasyRpgTcvn3DecodeByte(unsigned int aByte)
{
    return aByte < 256u ? KTcvn3ToUnicode[aByte] : aByte;
}

int EasyRpgTcvn3EncodeCodepoint(unsigned int aCodepoint)
{
    if (aCodepoint >= 0x20u && aCodepoint <= 0x7fu)
        return static_cast<int>(aCodepoint);
    for (unsigned int index = 0; index < 256u; ++index)
    {
        if (KTcvn3ToUnicode[index] == aCodepoint)
            return static_cast<int>(index);
    }
    return -1;
}

const unsigned char* EasyRpgGohuGlyphRows(unsigned int aCodepoint)
{
    const int encoded = EasyRpgTcvn3EncodeCodepoint(aCodepoint);
    if (encoded < 32 || encoded > 255)
        return 0;
    return KGohuGlyphRows + (encoded - 32) * 11;
}
